import SwiftUI
import TaskboardKit

/// 設定の窓
struct SettingsView: View {
    @Environment(AppModel.self) private var model
    @State private var draft = SettingsDraft()

    var body: some View {
        Form {
            Section("端末") {
                Toggle("通知", isOn: $draft.notify)
            }
        }
        .onDisappear { model.save(draft) }
    }

    private func save() {
        model.save(draft)
    }
}

